// spec: specs/customers-pricing.md §8 · кейсы .qa/tests/customers/cust-04 … cust-07 · несколько ролей (rep + admin) — пишется вручную (asUser)
// #1c5a6c (עבר QA 29.10, просьба клиента; context.md «Согласованные изменения»): נציג מכירות («testtest», rep.json) сам
//   добавляет клиентов — «לקוח חדש» в «לקוחות» и в «הזמנה מהודעה», без «ייבוא מאקסל»;
// #a6af81 (עבר QA 29.10): в «לקוחות» у נציג тот же переключатель «יצירת קישור הצטרפות», что у admin (по умолчанию вкл.);
//   выкл. → «שמירת הלקוח» (здесь); вкл. → клиент + ссылка (rep-join-link.spec.ts). В «הזמנה מהודעה» переключателя нет у обеих ролей.
//   клиент закрепляется за ним (sales_rep_id), виден в его списке; ⋮ у נציג — только «כרטיס לקוח»;
//   RLS customers_rep_insert: вставка с sales_rep_id другого נציג → 403 (42501).
// Данные: QA-AUTO-cust-1c5a6c-<ts>-*; заказы НЕ создаются (create_customer_order блокируется); afterAll — удаление через admin
//   (у נציג нет «מחיקה»). Иначе ломается счётчик «מציג 1–1 מתוך תוצאה אחת» в rep-direct.spec.ts / customers-access.spec.ts.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import {
  rowOf, openList, openNewCustomer, rest, deleteCustomersByPrefix,
  SUBTITLE_NO_LINK, SUBTITLE_LINK, BTN_SAVE, BTN_LINK, SWITCH_LINK,
} from './_customers';

test.describe.configure({ mode: 'serial' });

const PREFIX = `QA-AUTO-cust-1c5a6c-${Date.now().toString().slice(-7)}`;
const LISTED = `${PREFIX}-list`;
const FROM_MSG = `${PREFIX}-msg`;
let listedId = '';

async function profileId(admin: Page, fullName: string) {
  const r = await rest(admin, 'GET', `profiles?select=id&role=eq.sales_rep&full_name=eq.${encodeURIComponent(fullName)}`);
  expect(r.status).toBe(200);
  expect(r.json, `נציג «${fullName}»`).toHaveLength(1);
  return r.json[0].id as string;
}

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible({ timeout: 30_000 });
  const row = page.locator('div').filter({ hasText: employee }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

test.describe('customers — נציג מכירות מוסיף לקוח (#1c5a6c)', () => {
  test.afterAll(async ({ browser }) => {
    await deleteCustomersByPrefix(browser, test.info().project.use.baseURL, PREFIX);
  });

  test('נציג: ב«לקוחות» יש «לקוח חדש», אין «ייבוא מאקסל»; מתג «יצירת קישור הצטרפות» דלוק כברירת מחדל, כבוי → «שמירת הלקוח»; ולידציה בשני המצבים #1c5a6c #ea0fde #a6af81 @desktop @data', async ({ asUser }) => {
    const rep = await asUser('rep');
    await openList(rep);
    await expect(rep.getByRole('button', { name: 'לקוח חדש' })).toBeVisible();
    await expect(rep.getByRole('button', { name: 'ייבוא מאקסל' })).toHaveCount(0);

    const dlg = await openNewCustomer(rep);
    const sw = dlg.getByRole('switch', { name: SWITCH_LINK });
    const name = dlg.getByRole('textbox', { name: /^שם העסק/ });
    // #a6af81 «מה רצוי»: тот же переключатель, что у מפיץ; по умолчанию вкл. (как у admin, cust-01)
    await expect(sw).toHaveAttribute('aria-checked', 'true');
    await expect(dlg.getByText(SUBTITLE_LINK)).toBeVisible();
    await expect(dlg.getByRole('button', { name: BTN_LINK })).toBeVisible();

    // вкл.: валидация как у admin (F-15 AC)
    await dlg.getByRole('button', { name: BTN_LINK }).click();
    await expect(dlg.getByText('נא להזין שם עסק')).toBeVisible();
    await name.fill(`${PREFIX}-invalid`);
    await dlg.getByRole('textbox', { name: 'טלפון' }).fill('12');
    await dlg.getByRole('textbox', { name: 'אימייל' }).fill('bad@');
    await dlg.getByRole('button', { name: BTN_LINK }).click();
    await expect(dlg.getByText(/מספר טלפון קצר מדי/)).toBeVisible();
    await expect(dlg.getByText('כתובת אימייל לא תקינה')).toBeVisible();

    // выкл.: «שמירת הלקוח», подзаголовок без ссылки («מה רצוי» #a6af81 «מתג כבוי»)
    await sw.click();
    await expect(sw).toHaveAttribute('aria-checked', 'false');
    await expect(dlg.getByText(SUBTITLE_NO_LINK)).toBeVisible();
    await expect(dlg.getByRole('button', { name: BTN_SAVE })).toBeVisible();
    await expect(dlg.getByRole('button', { name: BTN_LINK })).toHaveCount(0);

    await name.fill('');
    await dlg.getByRole('button', { name: BTN_SAVE }).click();
    await expect(dlg.getByText('נא להזין שם עסק')).toBeVisible();
    await name.fill(`${PREFIX}-invalid`);
    await dlg.getByRole('button', { name: BTN_SAVE }).click();
    await expect(dlg.getByText(/מספר טלפון קצר מדי/)).toBeVisible();
    await expect(dlg.getByText('כתובת אימייל לא תקינה')).toBeVisible();
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(rep.getByRole('dialog')).toHaveCount(0);
    await expect(rowOf(rep, `${PREFIX}-invalid`)).toHaveCount(0);
  });

  test('נציג יוצר לקוח (מתג כבוי): POST 201 בלי קישור, ברשימה שלו, ⋮ — רק «כרטיס לקוח», כרטיס נפתח; אצל מנהל «נציג מכירות: testtest» ו-sales_rep_id של הנציג #1c5a6c #a6af81 @desktop @data', async ({ asUser }) => {
    const rep = await asUser('rep');
    await openList(rep);
    const dlg = await openNewCustomer(rep);
    const invites: string[] = [];
    rep.on('request', (r) => { if (/\/rest\/v1\/customer_invites/.test(r.url()) && r.method() === 'POST') invites.push(r.url()); });
    await dlg.getByRole('switch', { name: SWITCH_LINK }).click();
    await expect(dlg.getByRole('switch', { name: SWITCH_LINK })).toHaveAttribute('aria-checked', 'false');
    await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(LISTED);
    await dlg.getByRole('textbox', { name: 'איש קשר' }).fill('QA rep');
    await dlg.getByRole('textbox', { name: 'טלפון' }).fill('0501234569');
    const [resp] = await Promise.all([
      rep.waitForResponse((r) => /\/rest\/v1\/customers(\?|$)/.test(r.url()) && r.request().method() === 'POST'),
      dlg.getByRole('button', { name: BTN_SAVE }).click(),
    ]);
    expect(resp.status(), 'POST customers (נציג)').toBe(201);
    await expect(rep.getByRole('dialog')).toHaveCount(0, { timeout: 15_000 });
    await expect(rep.getByRole('heading', { name: 'החשבון נפתח' })).toHaveCount(0);
    expect(invites, 'переключатель выкл. — ссылка не создаётся').toHaveLength(0);

    const row = rowOf(rep, LISTED);
    await expect(row).toBeVisible({ timeout: 20_000 });
    await expect(row).toContainText('0501234569');
    await expect(rowOf(rep, '0531231235'), 'закреплённый ранее «test» по-прежнему в списке').toBeVisible();
    await row.getByRole('button', { name: 'פעולות' }).click();
    await expect(rep.getByRole('menuitem')).toHaveCount(1);
    await expect(rep.getByRole('menuitem', { name: 'כרטיס לקוח' })).toBeVisible();
    await rep.getByRole('menuitem', { name: 'כרטיס לקוח' }).click();
    await expect(rep).toHaveURL(/\/customers\/[0-9a-f-]{36}$/, { timeout: 20_000 });
    await expect(rep.getByRole('heading', { level: 1, name: LISTED })).toBeVisible({ timeout: 20_000 });
    listedId = rep.url().split('/').pop()!;

    const admin = await asUser('admin');
    await admin.goto(`/customers/${listedId}`);
    await expect(admin.getByRole('heading', { level: 1, name: LISTED })).toBeVisible({ timeout: 30_000 });
    const repBox = admin.getByRole('main').locator('div').filter({ has: admin.getByText('נציג מכירות', { exact: true }) }).filter({ hasText: 'testtest' }).last();
    await expect(repBox).toBeVisible();
    const testtestId = await profileId(admin, 'testtest');
    const c = await rest(admin, 'GET', `customers?select=sales_rep_id&id=eq.${listedId}`);
    expect(c.json?.[0]?.sales_rep_id, 'sales_rep_id = создавший נציג').toBe(testtestId);
  });

  test('RLS: נציג לא יכול להוסיף לקוח המשויך לנציג אחר — 403 (42501) #1c5a6c #ea0fde @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin');
    await openList(admin);
    const mosheId = await profileId(admin, 'משה כהן');

    const rep = await asUser('rep');
    await openList(rep);
    const own = await rest(rep, 'GET', 'customers?select=distributor_id&limit=1');
    expect(own.status).toBe(200);
    const distributorId = own.json[0].distributor_id as string;
    const r = await rest(rep, 'POST', 'customers', { name: `${PREFIX}-rls`, distributor_id: distributorId, sales_rep_id: mosheId });
    expect(r.status, `ответ ${JSON.stringify(r.json)}`).toBe(403);
    expect(r.json?.code).toBe('42501');
  });

  test('נציג אחר (משה כהן, כניסה כעובד בחלון נפרד) לא רואה את הלקוח החדש — «הלקוח לא נמצא.» #1c5a6c @desktop @data', async ({ asUser }) => {
    test.skip(!listedId, 'клиент из предыдущего теста не создан');
    const admin = await asUser('admin');
    await impersonate(admin, 'משה כהן');
    try {
      await admin.goto('/customers');
      await expect(admin.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible({ timeout: 30_000 });
      await expect(admin.getByText('עדיין אין לקוחות עסקיים')).toBeVisible({ timeout: 20_000 });
      await admin.goto(`/customers/${listedId}`);
      await expect(admin.getByText('הלקוח לא נמצא.')).toBeVisible({ timeout: 20_000 });
    } finally {
      await admin.goto('/customers');
      await admin.getByText('חזרה לחשבון הניהול').click();
      await expect(admin.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
    }
  });

  // #a6af81: в «הזמנה מהודעה» окно «לקוח חדש» без переключателя — так же у admin (rep-join-link.spec.ts), не ошибка.
  test('«הזמנה מהודעה» אצל נציג: «לקוח חדש» בלי מתג → «שמירת הלקוח» → הלקוח החדש נבחר בהזמנה; ההזמנה לא נשמרת #1c5a6c #ea0fde #a6af81 @desktop @data', async ({ asUser }) => {
    const rep = await asUser('rep');
    const saves: string[] = [];
    await rep.route('**/rest/v1/rpc/create_customer_order**', (r) => { saves.push(r.request().url()); return r.abort(); });
    await rep.goto('/orders/new');
    await expect(rep.getByRole('heading', { level: 1, name: 'הזמנה מהודעה' })).toBeVisible({ timeout: 30_000 });
    const dlg = await openNewCustomer(rep);
    await expect(dlg.getByRole('switch')).toHaveCount(0);
    await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(FROM_MSG);
    await dlg.getByRole('textbox', { name: 'טלפון' }).fill('0501234570');
    const [resp] = await Promise.all([
      rep.waitForResponse((r) => /\/rest\/v1\/customers(\?|$)/.test(r.url()) && r.request().method() === 'POST'),
      dlg.getByRole('button', { name: BTN_SAVE }).click(),
    ]);
    expect(resp.status(), 'POST customers из «הזמנה מהודעה»').toBe(201);
    await expect(rep.getByRole('dialog')).toHaveCount(0, { timeout: 15_000 });
    await expect(rep.getByRole('combobox')).toHaveValue(FROM_MSG);
    await expect(rep.getByText('0501234570')).toBeVisible();
    expect(saves, 'заказ не сохранялся').toHaveLength(0);

    await openList(rep);
    await expect(rowOf(rep, FROM_MSG)).toBeVisible({ timeout: 20_000 });
  });
});
